const VS = 60.0;
fn st(c: vec2f) -> vec4f { return sampleTarget(0u, c); }
fn vel(c: vec2f) -> vec2f { return st(c).rg * VS; }
fn visual_fcb_sim(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let P = pix();
  let res = vec2f(frame.resolution.x, frame.resolution.y);
  let back = P - vel(P) * 1.0;
  var v = vel(back);
  var dye = st(back).b;
  let vL = vel(P + vec2f(-1.0, 0.0));
  let vR = vel(P + vec2f( 1.0, 0.0));
  let vD = vel(P + vec2f(0.0, -1.0));
  let vU = vel(P + vec2f(0.0,  1.0));
  let divg = 0.25 * ((vR.x - vL.x) + (vU.y - vD.y));
  v -= vec2f(vR.x - vL.x, vU.y - vD.y) * clamp(divg, -2.0, 2.0) * 0.06;
  let t = time;
  let e1 = res * vec2f(0.34, 0.42);
  let e2 = res * vec2f(0.62, 0.56);
  let rr = res.x * res.x * 0.0035;
  let d1 = dot(P - e1, P - e1);
  let d2 = dot(P - e2, P - e2);
  v += vec2f( cos(t*0.9),  sin(t*0.9)) * exp(-d1/rr) * 5.0;
  v += vec2f(-sin(t*0.7),  cos(t*0.7)) * exp(-d2/rr) * 5.0;
  dye += (exp(-d1/(rr*0.5)) + exp(-d2/(rr*0.5))) * 0.22;
  if (!(v.x==v.x) || !(v.y==v.y) || !(dye==dye)) { v = vec2f(0.0); dye = 0.0; }
  v = clamp(v * 0.995, vec2f(-VS), vec2f(VS));
  dye = clamp(dye * 0.990, 0.0, 1.3);
  return vec4f(v / VS, dye, 1.0);
}

fn fcb_hsv(h: f32, s: f32, vv: f32) -> vec3f {
  let k = vec3f(1.0, 2.0/3.0, 1.0/3.0);
  let p = abs(fract(vec3f(h)+k)*6.0 - 3.0);
  return vv * mix(vec3f(1.0), clamp(p-1.0, vec3f(0.0), vec3f(1.0)), s);
}
fn visual_fcb_view(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let res = vec2f(frame.resolution.x, frame.resolution.y);
  // SHARED VIEW: every quadrant maps its local uv onto the FULL sim buffer,
  // so all four show the same fluid, one channel each.
  let sp = (uv * 0.5 + 0.5) * res;
  let s = sampleTarget(0u, sp);
  let VS = 60.0;
  let v = s.rg * VS;
  let dye = s.b;
  let ch = i32(color.r * 10.0 + 0.5);
  if (ch == 0) { return vec4f(vec3f(dye), 1.0); }
  if (ch == 1) {
    let e = res.x * 0.004;
    let hx = sampleTarget(0u, sp+vec2f(e,0.0)).b - sampleTarget(0u, sp-vec2f(e,0.0)).b;
    let hy = sampleTarget(0u, sp+vec2f(0.0,e)).b - sampleTarget(0u, sp-vec2f(0.0,e)).b;
    let n = normalize(vec3f(-hx, -hy, 0.25));
    return vec4f(n*0.5+0.5, 1.0);
  }
  if (ch == 2) {
    let ang = atan2(v.y, v.x) / 6.28318 + 0.5;
    let spd = clamp(length(v) / 14.0, 0.0, 1.0);
    return vec4f(fcb_hsv(ang, 0.9, 0.10 + 0.90*spd), 1.0);
  }
  var cols = array<vec3f,4>(vec3f(0.05,0.06,0.10), vec3f(0.90,0.30,0.25), vec3f(0.25,0.75,0.45), vec3f(0.30,0.55,0.95));
  var mat = 0;
  if (dye > 0.12) { mat = 1; }
  if (dye > 0.35) { mat = 2; }
  if (dye > 0.65) { mat = 3; }
  return vec4f(cols[mat], 1.0);
}
